__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"FORUMS",{enumerable:!0,get:function(){return l}}),Object.defineProperty(e,"forumOf",{enumerable:!0,get:function(){return n}});const l=[{id:"icc",group:"Milletleraras\u0131 ticari tahkim",short:"ICC",name:"ICC Uluslararas\u0131 Tahkim Divan\u0131 (Paris)",olaylar:["S\xf6zle\u015fmesinde ICC tahkim \u015fart\u0131 bulunan uluslararas\u0131 ticari uyu\u015fmazl\u0131klar: mal sat\u0131m\u0131 (CISG), in\u015faat (FIDIC), distrib\xfct\xf6rl\xfck ve acentelik, ortak giri\u015fim, lisans ve know-how, enerji tedariki.","Tahkim \u015fart\u0131n\u0131n ge\xe7erlili\u011fi ve kapsam\u0131, hakemin yetkisi (yetki itiraz\u0131), ihtiyati tedbir ve acil durum hakemi talepleri."],surec:["Tahkim talebi ve cevap; tek ya da \xfc\xe7 hakemli heyetin olu\u015fmas\u0131 (Divan atar ya da onaylar).","G\xf6rev Belgesi (Terms of Reference) ve usul takvimi; yaz\u0131l\u0131 beyanlar, belge ibraz\u0131 (\xe7o\u011fu zaman IBA Delil Kurallar\u0131), tan\u0131k ve bilirki\u015fi dinlenen duru\u015fma.","Karar tasla\u011f\u0131 Divan taraf\u0131ndan bi\xe7im y\xf6n\xfcnden incelenir; acil durum hakemi ve belirli tutar\u0131n alt\u0131nda h\u0131zland\u0131r\u0131lm\u0131\u015f usul vard\u0131r."],karar:"Hakem karar\u0131 kesin ve ba\u011flay\u0131c\u0131d\u0131r; taraflar esastan itiraz edemez. Heyet s\xf6zle\u015fmeyi, se\xe7ilen hukuku ve ticari team\xfclleri uygular; masraflar\u0131 ve vek\xe2let giderlerini de payla\u015ft\u0131r\u0131r.",yol:"Yaln\u0131zca tahkim yerinde iptal davas\u0131 (T\xfcrkiye'de tahkim yeri olan milletleraras\u0131 tahkimde 4686 s. MTK m.15'teki s\u0131n\u0131rl\u0131 sebepler). Ba\u015fka bir \xfclkede icras\u0131 i\xe7in New York S\xf6zle\u015fmesi uyar\u0131nca tan\u0131ma ve tenfiz; ret sebepleri m.V ile s\u0131n\u0131rl\u0131d\u0131r."},{id:"istac",group:"Milletleraras\u0131 ticari tahkim",short:"ISTAC",name:"\u0130stanbul Tahkim Merkezi (ISTAC)",olaylar:["S\xf6zle\u015fmesinde ISTAC \u015fart\u0131 bulunan ulusal ya da milletleraras\u0131 ticari uyu\u015fmazl\u0131klar: in\u015faat, enerji, sat\u0131m, \u015firket ortakl\u0131\u011f\u0131, finans.","Acil hakem ve h\u0131zland\u0131r\u0131lm\u0131\u015f tahkim talepleri."],surec:["ISTAC Tahkim Kurallar\u0131: tahkim talebi, cevap, hakem se\xe7imi ve onay\u0131, usul toplant\u0131s\u0131, yaz\u0131l\u0131 beyanlar, delil ve duru\u015fma.","Milletleraras\u0131 unsur varsa ve tahkim yeri T\xfcrkiye ise 4686 say\u0131l\u0131 Milletleraras\u0131 Tahkim Kanunu, yoksa HMK'n\u0131n tahkim h\xfck\xfcmleri (m.407 vd.) uygulan\u0131r."],karar:"Hakem karar\u0131 taraflar i\xe7in ba\u011flay\u0131c\u0131d\u0131r ve esastan denetlenmez.",yol:"T\xfcrkiye'de verilen karara kar\u015f\u0131 yaln\u0131zca iptal davas\u0131 (MTK m.15 ya da HMK m.439'daki s\u0131n\u0131rl\u0131 sebepler: ge\xe7ersiz tahkim anla\u015fmas\u0131, savunma hakk\u0131n\u0131n ihlali, yetki a\u015f\u0131m\u0131, kamu d\xfczenine ayk\u0131r\u0131l\u0131k vb.). Yabanc\u0131 \xfclkede icra i\xe7in New York S\xf6zle\u015fmesi."},{id:"lcia",group:"Milletleraras\u0131 ticari tahkim",short:"LCIA",name:"Londra Uluslararas\u0131 Tahkim Mahkemesi (LCIA)",olaylar:["LCIA \u015fart\u0131 ta\u015f\u0131yan uluslararas\u0131 ticari, finans ve deniz ticareti uyu\u015fmazl\u0131klar\u0131."],surec:["LCIA Kurallar\u0131: talep ve cevap, LCIA Mahkemesince hakem atanmas\u0131, yaz\u0131l\u0131 beyanlar, delil ve duru\u015fma; hakemin reddi ve acil tedbir mekanizmalar\u0131."],karar:"Kesin ve ba\u011flay\u0131c\u0131 karar; gerek\xe7eli ve yaz\u0131l\u0131.",yol:"Tahkim yeri \u0130ngiltere ise 1996 Tahkim Kanunu uyar\u0131nca s\u0131n\u0131rl\u0131 itirazlar; ba\u015fka \xfclkede New York S\xf6zle\u015fmesi ile tenfiz."},{id:"uncitral",group:"Milletleraras\u0131 ticari tahkim",short:"UNCITRAL",name:"UNCITRAL Tahkim Kurallar\u0131 (kurumsal olmayan / ad hoc tahkim)",olaylar:["Taraflar\u0131n bir kuruma ba\u011fl\u0131 olmadan UNCITRAL Kurallar\u0131n\u0131 se\xe7ti\u011fi ticari uyu\u015fmazl\u0131klar; deniz ticareti ve enerji s\xf6zle\u015fmelerinde yayg\u0131nd\u0131r."],surec:["Hakemleri taraflar se\xe7er, anla\u015famazlarsa atama makam\u0131 belirler; usul\xfc hakem heyeti kurallar \xe7er\xe7evesinde y\xfcr\xfct\xfcr."],karar:"Ba\u011flay\u0131c\u0131 hakem karar\u0131.",yol:"Tahkim yerinin hukukuna g\xf6re iptal davas\u0131; tenfiz i\xe7in New York S\xf6zle\u015fmesi."},{id:"cas",group:"Spor tahkimi",short:"CAS",name:"Spor Tahkim Mahkemesi (CAS, Lozan)",olaylar:["FIFA, UEFA ve di\u011fer uluslararas\u0131 federasyon kararlar\u0131na kar\u015f\u0131 temyiz: s\xf6zle\u015fme feshi ve tazminat (FIFA RSTP m.17), yeti\u015ftirme tazminat\u0131 ve dayan\u0131\u015fma katk\u0131s\u0131, transfer ve tescil.","Doping cezalar\u0131 (WADA Kodu), \u015fike ve m\xfcsabaka manip\xfclasyonu, uygunluk ve vatanda\u015fl\u0131k de\u011fi\u015fikli\u011fi, olimpiyat oyunlar\u0131nda ad hoc b\xf6l\xfcm."],surec:["Ola\u011fan usul (s\xf6zle\u015fmeye dayal\u0131 uyu\u015fmazl\u0131klar) ve temyiz usul\xfc (federasyon kararlar\u0131na kar\u015f\u0131).","Temyiz s\xfcresi, federasyon d\xfczenlemesinde ba\u015fka s\xfcre yoksa karar\u0131n tebli\u011finden itibaren 21 g\xfcnd\xfcr (CAS Kodu R49).","Panel olaylar\u0131 ve hukuku yeniden inceler (de novo, R57); duru\u015fma yap\u0131labilir; tan\u0131k ve bilirki\u015fi dinlenir."],karar:"Panel federasyon kurallar\u0131 ile uygulanacak hukuku (\xe7o\u011fu zaman \u0130svi\xe7re hukuku) uygular. \u015eike ve doping davalar\u0131nda ispat \xf6l\xe7\xfct\xfc \u201crahat kanaat\u201d (comfortable satisfaction) olarak an\u0131l\u0131r.",yol:"\u0130svi\xe7re Federal Mahkemesine yaln\u0131zca s\u0131n\u0131rl\u0131 sebeplerle iptal ba\u015fvurusu (\u0130svi\xe7re M\xd6HUK m.190)."},{id:"tff",group:"Spor tahkimi",short:"TFF TK",name:"TFF Tahkim Kurulu",olaylar:["Profesyonel Futbol Disiplin Kurulu (PFDK) ve Amat\xf6r Disiplin Kurulu cezalar\u0131na itiraz: saha olaylar\u0131, taraftar olaylar\u0131, seyircisiz oynama, para cezas\u0131.","Uyu\u015fmazl\u0131k \xc7\xf6z\xfcm Kurulu (U\xc7K) kararlar\u0131na itiraz: oyuncu-kul\xfcp alacaklar\u0131, hakl\u0131 fesih, menajer komisyonu.","Kul\xfcp lisans\u0131, tescil ve transfer, m\xfcsabaka tescili ile ilgili federasyon kararlar\u0131."],surec:["\u0130tiraz, federasyon talimatlar\u0131nda \xf6ng\xf6r\xfclen k\u0131sa s\xfcre i\xe7inde yaz\u0131l\u0131 olarak yap\u0131l\u0131r; Kurul dosya \xfczerinden ya da duru\u015fmal\u0131 inceler.","Hakem kararlar\u0131n\u0131n ve oyun kurallar\u0131n\u0131n uygulanmas\u0131 (saha i\xe7i takdir) kural olarak denetlenmez; hukuk kural\u0131na ayk\u0131r\u0131l\u0131k denetlenir."],karar:"Anayasa m.59/3 uyar\u0131nca sporun y\xf6netimi ve disipliniyle ilgili federasyon kararlar\u0131na kar\u015f\u0131 ancak zorunlu tahkim yoluna gidilebilir; Tahkim Kurulunun bu kararlar\u0131 kesindir.",yol:"Y\xf6netim ve disiplin kararlar\u0131nda yarg\u0131 yolu kapal\u0131d\u0131r; Anayasa Mahkemesi bu kararlara kar\u015f\u0131 bireysel ba\u015fvurular\u0131 konu bak\u0131m\u0131ndan yetkisizlik nedeniyle kabul edilemez bulmaktad\u0131r, A\u0130HM yolu ise a\xe7\u0131kt\u0131r (Ali R\u0131za ve Di\u011ferleri/T\xfcrkiye, 2020). Alacak ve menajer \xfccreti gibi di\u011fer uyu\u015fmazl\u0131klarda 2022'den beri bir ay i\xe7inde HMK m.439'a g\xf6re iptal davas\u0131 a\xe7\u0131labilir (5894 s.K. m.6/6)."},{id:"ihtk",group:"Komisyonlar",short:"\u0130HTK",name:"\u0130nsan Haklar\u0131 Tazminat Komisyonu (Adalet Bakanl\u0131\u011f\u0131)",olaylar:["Ceza soru\u015fturmas\u0131 ve kovu\u015fturmalar\u0131 ile hukuk ve idari yarg\u0131 davalar\u0131n\u0131n makul s\xfcrede sonu\xe7land\u0131r\u0131lmamas\u0131: 7499 say\u0131l\u0131 Kanunla (2024) yarg\u0131lama s\xfcrerken ya da kesin karar\u0131n \xf6\u011frenilmesinden itibaren bir ay i\xe7inde do\u011frudan m\xfcracaat edilebilir.","Mahkeme kararlar\u0131n\u0131n ge\xe7 ya da eksik icra edilmesi veya hi\xe7 icra edilmemesi: Anayasa Mahkemesi ve A\u0130HM'den Komisyona y\xf6nlendirilen ba\u015fvurular.","Ge\xe7mi\u015fte geni\u015fletilen alanlar (2014, A\u0130HM'de bekleyen ba\u015fvurular i\xe7in): kamula\u015ft\u0131rma ve irtifak davalar\u0131nda uzun yarg\u0131lama ve enflasyon nedeniyle de\u011fer kayb\u0131; ceza infaz kurumunda disiplin cezas\u0131 itirazlar\u0131nda savunma hakk\u0131n\u0131n k\u0131s\u0131tlanmas\u0131, T\xfcrk\xe7e olmayan mektuplar\u0131n ve yay\u0131nlar\u0131n engellenmesi."],surec:["Komisyon Adalet Bakanl\u0131\u011f\u0131nda g\xf6revli dokuz h\xe2kim ve savc\u0131dan olu\u015fur, \xfc\xe7er ki\u015filik heyetlerle \xe7al\u0131\u015f\u0131r; inceleme dosya \xfczerinden yap\u0131l\u0131r, ilgili yarg\u0131 dosyas\u0131 ve idarenin g\xf6r\xfc\u015f\xfc getirtilir.","Komisyon dokuz ay i\xe7inde karar verir; tazminat belirlenirken A\u0130HM ve Anayasa Mahkemesinin benzer ba\u015fvurulardaki \xf6l\xe7\xfctleri esas al\u0131n\u0131r. Do\u011frudan makul s\xfcre m\xfcracaat\u0131nda yaln\u0131zca manevi tazminata h\xfckmedilir."],karar:"Komisyon ihlali tespit ederse ba\u015fvurana tazminat \xf6denmesine karar verir; g\xf6rev alan\u0131 d\u0131\u015f\u0131ndaki ya da s\xfcresinde yap\u0131lmayan ba\u015fvurular\u0131 reddeder.",yol:"Komisyon karar\u0131na kar\u015f\u0131 tebli\u011fden itibaren on be\u015f g\xfcn i\xe7inde, Komisyon arac\u0131l\u0131\u011f\u0131yla Ankara B\xf6lge \u0130dare Mahkemesine itiraz edilir; bu karar kesindir. Ard\u0131ndan Anayasa Mahkemesine bireysel ba\u015fvuru yolu a\xe7\u0131kt\u0131r."},{id:"sigorta",group:"Komisyonlar",short:"STK",name:"Sigorta Tahkim Komisyonu",olaylar:["Sigortal\u0131, lehtar ya da zarar g\xf6ren ile Komisyona \xfcye sigorta kurulu\u015fu aras\u0131ndaki uyu\u015fmazl\u0131klar: kasko, trafik sigortas\u0131 (de\u011fer kayb\u0131, destekten yoksun kalma), konut ve yang\u0131n, sa\u011fl\u0131k, hayat ve kredi hayat, nakliyat, mesleki sorumluluk, DASK, tar\u0131m sigortas\u0131.","Tazminat\u0131n reddi, eksik \xf6denmesi, istisna ve muafiyet tart\u0131\u015fmalar\u0131, beyan y\xfck\xfcml\xfcl\xfc\u011f\xfcn\xfcn ihlali."],surec:["\xd6nce sigorta kurulu\u015funa yaz\u0131l\u0131 ba\u015fvuru yap\u0131l\u0131r; \u015firket reddederse ya da 15 i\u015f g\xfcn\xfc i\xe7inde cevap vermezse Komisyona ba\u015fvurulur (5684 s.K. m.30).","Ba\u015fvuru raport\xf6rce \xf6n incelemeden ge\xe7er; uyu\u015fmazl\u0131k hakem heyeti (tutara g\xf6re tek ya da \xfc\xe7 hakem) dosyay\u0131 inceler, gerekirse bilirki\u015fi raporu al\u0131r; HMK h\xfck\xfcmleri uygulan\u0131r. Karar, hakem atand\u0131ktan sonra d\xf6rt ay i\xe7inde verilir."],karar:"Hakem karar\u0131 ilam niteli\u011findedir; tazminat, faiz, yarg\u0131lama gideri ve vek\xe2let \xfccretine h\xfckmedilir.",yol:"Belirli tutar\u0131n \xfczerindeki uyu\u015fmazl\u0131klarda (2026'da 35.000 TL ve \xfczeri) karara kar\u015f\u0131 bildirimden itibaren 10 g\xfcn i\xe7inde itiraz hakem heyetine bir kez yaz\u0131l\u0131 itiraz edilir; itiraz icray\u0131 durdurur, adli tatil s\xfcreyi uzatmaz. Daha y\xfcksek tutarlarda (2026'da 383.000 TL'yi a\u015fan) itiraz hakem heyeti karar\u0131na kar\u015f\u0131 iki hafta i\xe7inde Yarg\u0131tay'a temyiz yolu a\xe7\u0131kt\u0131r (5684 s.K. m.30/12). Parasal s\u0131n\u0131rlar her y\u0131l g\xfcncellenir; ba\u015fvuru tarihindeki s\u0131n\u0131r esas al\u0131n\u0131r."},{id:"baro",group:"Komisyonlar",short:"D\u0130S\u0130PL\u0130N",name:"Baro ve TBB Disiplin Kurullar\u0131 (avukatlar\u0131n disiplin yarg\u0131lamas\u0131)",olaylar:["Avukatl\u0131k Kanunu m.134-135 (7571 say\u0131l\u0131 Kanunla 2025'te yeniden d\xfczenlendi) disiplin cezas\u0131n\u0131 gerektiren eylemleri cezaya g\xf6re sayar: uyarma (\xf6r. mazeretsiz duru\u015fmaya gelmemek, meslekta\u015f\u0131 kamuoyu \xf6n\xfcnde k\xfc\xe7\xfck d\xfc\u015f\xfcrmek), k\u0131nama (\xf6r. reklam yasa\u011f\u0131n\u0131 ihlal, \xf6zen y\xfck\xfcml\xfcl\xfc\u011f\xfcn\xfc ihlal ederek hak kayb\u0131na yol a\xe7mak), para cezas\u0131 (\xf6r. m\xfcvekkilinin zarar\u0131na menfaat sa\u011flamak), i\u015ften \xe7\u0131karma (\xf6r. resm\xee s\u0131fatla g\xf6rev yapt\u0131\u011f\u0131 i\u015fte avukatl\u0131k yapmak) ve meslekten \xe7\u0131karma.","\u015eik\xe2yetler \xe7o\u011funlukla m\xfcvekkilden gelir: tahsil edilen paran\u0131n verilmemesi, i\u015fin takipsiz b\u0131rak\u0131lmas\u0131, s\xfcre ka\xe7\u0131r\u0131lmas\u0131, ileti\u015fimsizlik; ayr\u0131ca reklam yasa\u011f\u0131, meslekta\u015flar aras\u0131 ili\u015fkiler ve yasakl\u0131 i\u015flerde avukatl\u0131k."],surec:["\u015eik\xe2yet \xfczerine baro y\xf6netim kurulu \xf6n inceleme yapar, gerekirse soru\u015fturma yapt\u0131r\u0131r ve disiplin kovu\u015fturmas\u0131 a\xe7\u0131lmas\u0131na ya da kovu\u015fturmaya yer olmad\u0131\u011f\u0131na karar verir.","Kovu\u015fturma baro disiplin kurulunda y\xfcr\xfcr: avukat\u0131n savunmas\u0131 al\u0131n\u0131r, belgeler incelenir, gerekirse tan\u0131k ve \u015fik\xe2yet\xe7i dinlenir. Avukat bir meslekta\u015f\u0131n\u0131 vekil olarak getirebilir; son s\xf6z hakk\u0131nda kovu\u015fturma yap\u0131lan avukat\u0131nd\u0131r.","Disiplin kovu\u015fturmas\u0131, eylemin baroca \xf6\u011frenilmesinden ve i\u015flenmesinden itibaren kanundaki zamana\u015f\u0131m\u0131 s\xfcreleri ge\xe7tikten sonra a\xe7\u0131lamaz (Av.K. m.154)."],karar:"Kurul uyarma, k\u0131nama, para cezas\u0131 (20.000-200.000 TL; her y\u0131l yeniden de\u011ferleme oran\u0131nda artar), \xfc\xe7 aydan iki y\u0131la kadar i\u015ften \xe7\u0131karma ya da meslekten \xe7\u0131karma cezas\u0131 verir veya disiplin cezas\u0131 verilmesine yer olmad\u0131\u011f\u0131na karar verir (Av.K. m.135).",yol:"Baro disiplin kurulu karar\u0131na kar\u015f\u0131 ilgili avukat ve Cumhuriyet savc\u0131s\u0131 tebli\u011fden itibaren otuz g\xfcn i\xe7inde TBB Disiplin Kuruluna itiraz edebilir (Av.K. m.157). TBB Disiplin Kurulu dosya \xfczerinden inceler; i\u015ften ya da meslekten \xe7\u0131karmada istem \xfczerine ya da kendili\u011finden duru\u015fma yapabilir. Uyarma, k\u0131nama ve para cezas\u0131 kararlar\u0131 kesindir; di\u011ferleri Adalet Bakanl\u0131\u011f\u0131n\u0131n onay\u0131yla kesinle\u015fir. Kesinle\u015fen karara kar\u015f\u0131 idari yarg\u0131 yolu a\xe7\u0131kt\u0131r."}],n=n=>l.find(l=>l.id===n)},764,[]);
